<?php
namespace App\Controllers; use App\Helpers\{View,Csrf,Flash,Env}; use App\Middlewares\AdminMiddleware; use App\Repositories\{ProductRepository,CategoryRepository};
final class AdminProductController {
 public function index():void{AdminMiddleware::handle();View::render('admin/products/index',['title'=>'Productos','products'=>(new ProductRepository())->all()]);}
 public function create():void{AdminMiddleware::handle();View::render('admin/products/form',['title'=>'Nuevo producto','categories'=>(new CategoryRepository())->all(true),'product'=>null]);}
 public function store():void{AdminMiddleware::handle();Csrf::validate();$d=$this->data();$id=(new ProductRepository())->create($d);$this->image($id);Flash::set('success','Producto creado correctamente.');header('Location: /admin/products');}
 public function edit(string $id):void{AdminMiddleware::handle();$p=(new ProductRepository())->find((int)$id);if(!$p){http_response_code(404);exit('Producto no encontrado');}View::render('admin/products/form',['title'=>'Editar producto','categories'=>(new CategoryRepository())->all(true),'product'=>$p]);}
 public function update(string $id):void{AdminMiddleware::handle();Csrf::validate();(new ProductRepository())->update((int)$id,$this->data());$this->image((int)$id);Flash::set('success','Producto actualizado.');header('Location: /admin/products');}
 public function delete(string $id):void{AdminMiddleware::handle();Csrf::validate();(new ProductRepository())->delete((int)$id);Flash::set('success','Producto eliminado.');header('Location: /admin/products');}
 private function data():array{$price=max(0,(float)($_POST['price']??0));return ['category_id'=>(int)($_POST['category_id']??0),'name'=>trim($_POST['name']??''),'description'=>trim($_POST['description']??''),'price'=>$price,'stock'=>max(0,(int)($_POST['stock']??0)),'points_reward'=>max(0,(int)($_POST['points_reward']??floor($price))),'status'=>in_array($_POST['status']??'ACTIVE',['ACTIVE','INACTIVE'],true)?$_POST['status']:'ACTIVE','is_featured'=>isset($_POST['is_featured'])?1:0];}
 private function image(int $id):void{if(empty($_FILES['image']['tmp_name'])||$_FILES['image']['error']!==UPLOAD_ERR_OK)return;$max=(int)Env::get('MAX_UPLOAD_MB',5)*1024*1024;if($_FILES['image']['size']>$max)throw new \RuntimeException('Imagen demasiado grande.');$mime=(new \finfo(FILEINFO_MIME_TYPE))->file($_FILES['image']['tmp_name']);$map=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($map[$mime]))throw new \RuntimeException('Formato de imagen no permitido.');$name=bin2hex(random_bytes(16)).'.'.$map[$mime];$dir=dirname(__DIR__,2).'/storage/uploads';if(!is_dir($dir))mkdir($dir,0775,true);move_uploaded_file($_FILES['image']['tmp_name'],$dir.'/'.$name);(new ProductRepository())->saveImage($id,'/uploads/'.$name);}
}
